#include <iostream>
struct Base {
    void f() { std::cout << "B"; }
    virtual void g() { std::cout << "B"; }
};
struct Derived : Base {
    void f() { std::cout << "D"; }
    void g() override { std::cout << "D"; }
};
int main() {
    Derived d;
    Base* p = &d;
    p->f();
    p->g();
    std::cout << "\n";
}
